input.newString:
func (h *Head) loadChunkSnapshot() (int, int, map[chunks.HeadSeriesRef]*memSeries, error) {
	files, err := os.ReadDir(h.opts.ChunkDirRoot)
	if err != nil {
		return 0, 0, nil, errors.Wrap(err, "find last chunk snapshot")
	}

	// A snapshot cannot be from a WAL segment that is ahead of the last WAL
	// segment currently on disk. This can happen when the WAL is reset after
	// a snapshot was taken. Such a snapshot is stale and must not be replayed.
	wlast := -1
	if h.wal != nil {
		_, wlast, err = wlog.Segments(h.wal.Dir())
		if err != nil {
			return 0, 0, nil, errors.Wrap(err, "find last wal segment")
		}
	}

	maxIdx, maxOffset := -1, -1
	maxFileName := ""
	for i := 0; i < len(files); i++ {
		fi := files[i]
		name := fi.Name()
		if !strings.HasPrefix(name, chunkSnapshotPrefix) {
			continue
		}
		if !fi.IsDir() {
			return 0, 0, nil, errors.Wrap(errors.Errorf("chunk snapshot %s is not a directory", name), "find last chunk snapshot")
		}

		splits := strings.Split(name[len(chunkSnapshotPrefix):], ".")
		if len(splits) != 2 {
			continue
		}

		idx, err := strconv.Atoi(splits[0])
		if err != nil {
			continue
		}
		offset, err := strconv.Atoi(splits[1])
		if err != nil {
			continue
		}

		if wlast >= 0 && idx > wlast {
			// This snapshot is ahead of the WAL, so it cannot be valid. Remove
			// it, otherwise it would keep being selected on every restart.
			snapshotDir := filepath.Join(h.opts.ChunkDirRoot, name)
			level.Warn(h.logger).Log(
				"msg", "removing chunk snapshot that is ahead of the WAL",
				"snapshot", snapshotDir,
				"snapshot_index", idx,
				"wal_index", wlast,
			)
			if err := os.RemoveAll(snapshotDir); err != nil {
				return 0, 0, nil, errors.Wrap(err, "remove chunk snapshot ahead of WAL")
			}
			continue
		}

		if idx > maxIdx {
			maxIdx, maxOffset = idx, offset
			maxFileName = filepath.Join(h.opts.ChunkDirRoot, name)
		} else if idx == maxIdx {
			if offset > maxOffset {
				maxIdx, maxOffset = idx, offset
				maxFileName = filepath.Join(h.opts.ChunkDirRoot, name)
			}
		}
	}

